      --text: #ffffffcf; --text-2: #ffffffa6; --text-3: #ffffff80;
      --akzent: #529cca; --akzent-dunkel: #6bb0dc; --akzent-hell: #529cca2b;
      --krit-bg: #5c2c2c; --krit: #ffb9b3; --warn-bg: #4d3f1f; --warn: #f1d58e; --ok-bg: #234232; --ok: #a6dcbb; --neutral-bg: #2f2f2f; --neutral: #c4c3c0;
      --popover: 0 0 0 1px #ffffff1f, 0 8px 24px #00000080;
