  .aktionen .knopf:not(.gruen):not(.primaer) { border-color: transparent; background: transparent; color: var(--text-2); }
  .aktionen .knopf:not(.gruen):not(.primaer):hover { background: var(--hover); color: var(--text); }
  .knopf.primaer { background: var(--text); color: var(--bg); border-color: var(--text); } .knopf.primaer:hover { opacity: .88; background: var(--text); }
  .knopf.aktiv { background: var(--auswahl); color: var(--akzent-dunkel); border-color: transparent; }
  .knopf.klein { height: 28px; padding: 0 9px; font-size: 12.5px; }
  .knopf.gruen { background: var(--akzent); border-color: var(--akzent); color: #fff; } .knopf.gruen:hover { background: var(--akzent-dunkel); }
  .knopf.rot { color: var(--krit); } .knopf.rot:hover { background: var(--krit-bg); }
  .knopf.dunkel { background: var(--akzent); border-color: var(--akzent); color: #fff; } .knopf.dunkel:hover { background: var(--akzent-dunkel); }
  .knopf[disabled] { color: var(--text-3); cursor: not-allowed; background: transparent; }
  .knopf .num { margin-left: 2px; padding: 0 6px; border-radius: 999px; background: #ffffff33; font-size: 12px; }
  .leise-knopf { color: var(--text-2); } .leise-knopf.empfohlen { border-color: var(--akzent); color: var(--akzent-dunkel); background: var(--akzent-hell); }
  select, .bearbeiter input, .cp-form input { height: 30px; border: 1px solid var(--linie-2); border-radius: 6px; background: var(--flaeche); color: var(--text); font: 13px var(--sans); padding: 0 8px; }
  .bearbeiter input:focus, .cp-form input:focus { outline: none; border-color: var(--akzent); box-shadow: 0 0 0 3px var(--akzent-hell); }
  .bearbeiter input.fehlt { border-color: var(--krit); box-shadow: 0 0 0 3px var(--krit-bg); }

  /* Seitenkopf mit Savings */
  .kopf-unten { max-width: 1480px; margin: 0 auto; padding: 36px 40px 0; display: flex; align-items: flex-end; gap: 32px; flex-wrap: wrap; }
  .seitenkopf { flex: 1 1 320px; min-width: 0; }
  .seitentitel { font-size: 32px; line-height: 1.15; font-weight: 700; letter-spacing: -.02em; }
  .untertitel { margin-top: 6px; color: var(--text-3); font-size: 14px; }
  .hero { position: relative; flex: 1 1 360px; max-width: 520px; display: flex; flex-direction: column; gap: 6px; outline: none; }
  .hero-kopf { display: flex; align-items: center; gap: 6px; color: var(--text-3); font-size: 13px; } .hero-titel { font-weight: 600; color: var(--text-2); } .hero-kopf .i { display: none; }
  .hero-zahlen { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  .hero-wert { font-size: 28px; font-weight: 700; letter-spacing: -.02em; color: var(--text); }
  .hero-ziel { color: var(--text-3); font-size: 13px; } .hero-anteil { color: var(--text-3); font-size: 13px; margin-left: auto; }
  .hero-balken { height: 4px; border-radius: 999px; background: var(--linie); overflow: hidden; } .hero-balken div { height: 100%; min-width: 3px; background: var(--akzent); border-radius: 999px; }
  .hero::after, .tip::after { content: attr(data-tip); position: absolute; padding: 8px 10px; background: var(--flaeche); color: var(--text); font: 12.5px/1.45 var(--sans); border-radius: 8px; box-shadow: var(--popover); opacity: 0; pointer-events: none; transition: opacity .1s; z-index: 30; }
  .hero::after { left: 0; top: calc(100% + 6px); max-width: 420px; }
  .hero:hover::after, .hero:focus-visible::after, .tip:hover::after, .tip:focus-visible::after { opacity: 1; }
  .chips { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-left: auto; }
  .lokal, .streak, .rang { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 8px; border-radius: 4px; background: var(--neutral-bg); color: var(--neutral); font-size: 12.5px; font-weight: 500; white-space: nowrap; border: 0; }
  .lokal { cursor: help; } .lokal .puls { color: #2b8a5b; }
  .streak .i { color: #c47f17; width: 12px; height: 12px; } 
  .rang .i { color: #c47f17; width: 12px; height: 12px; } .rang b { font-weight: 600; color: var(--text); }
  .puls { position: relative; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  .puls::after { content: ""; position: absolute; inset: -3px; border-radius: 50%; border: 1px solid currentColor; animation: puls 2s ease-out infinite; }
  @keyframes puls { from { transform: scale(.6); opacity: .8; } to { transform: scale(1.7); opacity: 0; } }

  main { max-width: 1480px; margin: 0 auto; padding: 24px 40px 56px; }
  .banner { display: flex; gap: 10px; align-items: flex-start; border-radius: 6px; background: var(--neutral-bg); padding: 10px 14px; margin-bottom: 20px; color: var(--text-2); font-size: 13px; }

  /* Kennzahlen: eine ruhige Zeile */
  .kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin-bottom: 28px; border-top: 1px solid var(--linie); border-bottom: 1px solid var(--linie); }
  .kpi { padding: 16px 20px 16px 0; } .kpi + .kpi { padding-left: 20px; border-left: 1px solid var(--linie); }
  .kpi-titel { font-size: 13px; color: var(--text-3); font-weight: 500; }
  .kpi-wert { font-size: 28px; line-height: 1.2; font-weight: 600; letter-spacing: -.02em; margin: 4px 0 2px; color: var(--text); }
  .kpi.krit .kpi-wert { color: var(--krit); } .kpi.warn .kpi-wert { color: var(--warn); }
  .kpi-unter { font-size: 12.5px; color: var(--text-3); }

  /* Filter */
  .filter { display: flex; flex-wrap: wrap; align-items: center; gap: 2px; margin: 0 0 20px; }
  .reiter { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border: 0; border-radius: 6px; background: none; color: var(--text-3); font: 500 13.5px var(--sans); cursor: pointer; }
  .reiter:hover { background: var(--hover); color: var(--text); }
  .reiter[aria-selected="true"] { background: var(--hover); color: var(--text); }
  .reiter .num { font-size: 12.5px; color: var(--text-3); }
  .sortierung { margin-left: auto; font-size: 13px; color: var(--text-3); display: flex; align-items: center; gap: 8px; }

  h2 { font-size: 13px; font-weight: 600; color: var(--text-3); margin: 0 0 10px; display: flex; align-items: center; gap: 8px; }
  .bereich { margin-bottom: 36px; }
  .zaehler { font-size: 12px; font-weight: 500; color: var(--text-3); }

  /* Arbeitsraum: Queue links, Seite rechts */
  .arbeitsraum { display: grid; grid-template-columns: minmax(300px, 360px) minmax(0, 1fr); gap: 40px; align-items: start; margin-bottom: 56px; }
  .queue { position: sticky; top: 68px; max-height: calc(100vh - 84px); overflow: auto; display: flex; flex-direction: column; gap: 18px; padding-right: 8px; scrollbar-width: thin; }
  .gruppe { flex: none; }
  .g-kopf { display: flex; align-items: center; gap: 8px; width: 100%; padding: 4px 8px; border: 0; border-radius: 6px; background: none; color: var(--text-3); font: 600 12.5px var(--sans); text-align: left; }
  button.g-kopf { cursor: pointer; } button.g-kopf:hover { background: var(--hover); color: var(--text); }
  .g-kopf[aria-selected="true"] { background: var(--auswahl); color: var(--akzent-dunkel); }
  .g-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text); font-size: 13.5px; }
  .g-kopf .badge { height: 18px; font-size: 11.5px; }
  .zeile { display: flex; flex-direction: column; gap: 4px; width: 100%; text-align: left; padding: 8px 10px; margin-top: 2px; border: 0; border-radius: 6px; background: none; color: var(--text); font: 13.5px var(--sans); cursor: pointer; }
  .zeile:hover { background: var(--hover); } .zeile[aria-selected="true"] { background: var(--auswahl); }
  .zeile .z-art { order: 0; font-weight: 500; line-height: 1.35; } .zeile .z-oben { order: 1; } .zeile .z-unten { order: 2; }
  .z-oben, .z-unten { display: flex; align-items: center; gap: 8px; } .z-oben .meta { margin-left: auto; } .z-unten { justify-content: space-between; color: var(--text-3); font-size: 12.5px; }
  .z-jahr { font-size: 12.5px; font-weight: 500; color: var(--text-2); white-space: nowrap; font-variant-numeric: tabular-nums; }
  .meta { color: var(--text-3); font-size: 12.5px; white-space: nowrap; }

  /* Seite (Detail) */
  .detail { min-width: 0; }
  .detail .karte, .akte { max-width: 780px; }
  .detail .karte:not([hidden]), .detail .akte:not([hidden]) { animation: einblenden .16s ease-out; }
  @keyframes einblenden { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
  .karte { background: none; border: 0; padding: 0; display: flex; flex-direction: column; gap: 20px; min-width: 0; transition: transform .22s ease, opacity .22s ease; }
  .karte.weg { transform: translateX(24px); opacity: 0; }
  .karte header { display: flex; flex-direction: column; gap: 8px; }
  .kopfzeile { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; min-width: 0; }
  h3 { font-size: 26px; line-height: 1.2; font-weight: 700; letter-spacing: -.02em; color: var(--text); }
  .id, .kat { font-size: 12.5px; color: var(--text-3); font-weight: 500; }
  .kat::before { content: "·"; margin-right: 8px; }
  .titel { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  .art { font-size: 15px; color: var(--text-2); font-weight: 500; flex-basis: 100%; order: 3; }
  .titel .meta { margin-left: 0; order: 2; }
  .reiterleiste { display: flex; gap: 20px; border-bottom: 1px solid var(--linie); }
  .kreiter { border: 0; background: none; padding: 6px 0 8px; margin-bottom: -1px; border-bottom: 2px solid transparent; font: 500 13.5px var(--sans); color: var(--text-3); cursor: pointer; white-space: nowrap; }
  .kreiter:hover { color: var(--text); } .kreiter[aria-selected="true"] { color: var(--text); border-bottom-color: var(--text); }
  .tafel { display: flex; flex-direction: column; gap: 16px; }

  /* Empfehlung: Hinweisbox in der Farbe der Bedeutung */
  .empfehlung { display: flex; flex-direction: column; gap: 4px; padding: 14px 16px; border-radius: 6px; background: var(--neutral-bg); color: var(--text); }
  .empfehlung.krit { background: var(--krit-bg); } .empfehlung.warn { background: var(--warn-bg); } .empfehlung.ok { background: var(--ok-bg); }
  .empf-kopf { display: flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 600; color: var(--text-2); }
  .empfehlung.krit .empf-kopf { color: var(--krit); } .empfehlung.warn .empf-kopf { color: var(--warn); } .empfehlung.ok .empf-kopf { color: var(--ok); }
  .empf-text { font-size: 16px; line-height: 1.4; font-weight: 600; letter-spacing: -.005em; color: var(--text); }
  .empf-grund { font-size: 13.5px; color: var(--text-2); }
  .empf-fuss { margin-top: 6px; font-size: 12px; color: var(--text-3); }
  .empf-aktion { margin-top: 8px; }
  .empfehlung .num { color: inherit; }

  /* Eigenschaften wie eine Notion-Seite */
  .gitter { display: flex; flex-direction: column; margin: 0; }
  .gitter div { display: flex; align-items: baseline; gap: 16px; padding: 5px 0; min-width: 0; }
  .gitter dt { flex: 0 0 150px; font-size: 13.5px; color: var(--text-3); } .gitter dd { margin: 0; font-size: 14px; overflow-wrap: anywhere; }
  .befunde { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; font-size: 14px; }
  .befund { display: flex; align-items: flex-start; gap: 8px; color: var(--text-2); } .befund > span:not(.tip) { flex: 1; min-width: 0; }
  .befund > .i, .befund .tip { margin-top: 4px; }
  .befund.krit, .befund.warn { padding: 8px 12px; border-radius: 6px; font-size: 13.5px; }
  .befund.krit { background: var(--krit-bg); color: var(--krit); } .befund.warn { background: var(--warn-bg); color: var(--warn); }
  .befund.ok > .i { color: #2b8a5b; } .befund.neutral > .i { width: 6px; height: 6px; margin: 9px 4px 0; color: var(--linie-2); }
  .tip { position: relative; display: inline-flex; color: var(--text-3); cursor: help; outline: none; }
  .tip::after { right: 0; bottom: calc(100% + 6px); width: max-content; max-width: 320px; white-space: normal; transform: translateY(2px); }
  .tip:hover::after, .tip:focus-visible::after { transform: none; }
  .text { color: var(--text-2); font-size: 14px; }
  pre { white-space: pre-wrap; background: var(--neutral-bg); padding: 12px 14px; border-radius: 6px; font: 13.5px/1.6 var(--sans); margin: 8px 0 0; color: var(--text); }
  pre.original { margin: 0; max-height: 360px; overflow: auto; }
  details { padding-top: 4px; } summary { cursor: pointer; font-size: 13.5px; font-weight: 500; color: var(--text-2); }
  .hinweis { display: flex; gap: 6px; align-items: center; color: var(--warn); font-size: 13px; margin: 8px 0 0; }
  .entwurf pre { max-height: 280px; overflow: auto; }

  /* Tags */
  .badge { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: 4px; font: 500 12.5px var(--sans); white-space: nowrap; background: var(--neutral-bg); color: var(--neutral); border: 0; }
  .badge .i { display: none; } .badge .puls { width: 6px; height: 6px; }
  .badge.krit { background: var(--krit-bg); color: var(--krit); } .badge.warn { background: var(--warn-bg); color: var(--warn); } .badge.ok { background: var(--ok-bg); color: var(--ok); }
  .maske { font-family: var(--mono); font-size: .9em; background: var(--neutral-bg); color: var(--text-2); border-radius: 3px; padding: 0 4px; }

  /* Aktionen */
  .aktionsleiste { display: flex; flex-direction: column; gap: 10px; align-items: stretch; padding-top: 16px; border-top: 1px solid var(--linie); }
  .aktionsleiste form, form.entscheiden { margin: 0; display: inline-flex; }
  .entscheidung, .weiter { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; } .weiter .leise { margin-right: 4px; }

  /* Tabellen */
  .tabelle { overflow: auto; border-top: 1px solid var(--linie); }
  table { border-collapse: collapse; width: 100%; font-size: 13.5px; }
  th { text-align: left; font-size: 12.5px; font-weight: 500; color: var(--text-3); padding: 8px 12px 8px 0; border-bottom: 1px solid var(--linie); position: sticky; top: 0; background: var(--bg); }
  td { border-bottom: 1px solid var(--linie); padding: 10px 12px 10px 0; vertical-align: top; } tr:last-child td { border-bottom: 0; }
  td .badge { margin: 0 2px 4px 0; }
  .leer { color: var(--text-3); font-size: 14px; padding: 28px 0; }

  /* Historie, Übergabe, Sammelakte */
  .historie h4 { margin: 14px 0 4px; font-size: 12.5px; font-weight: 600; color: var(--text-3); }
  .historie ul, .historie ol { margin: 0; padding-left: 18px; font-size: 13.5px; color: var(--text-2); }
  .zeitleiste { list-style: none; padding-left: 0 !important; border-left: 1px solid var(--linie-2); margin-left: 4px !important; }
  .zeitleiste li { position: relative; padding: 0 0 8px 14px; display: flex; flex-direction: column; }
  .zeitleiste li::before { content: ""; position: absolute; left: -4px; top: 7px; width: 7px; height: 7px; border-radius: 50%; background: var(--linie-2); }
  .uebergabe { background: var(--neutral-bg); border-radius: 6px; padding: 16px 20px; margin: 0 0 24px; }
  .ueb-raster { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; } .uebergabe ul { margin: 6px 0; padding-left: 18px; font-size: 13.5px; }
  .akte { display: flex; flex-direction: column; gap: 18px; } .akte header { display: flex; align-items: center; gap: 10px; }
  .akte-liste { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
  .akte-liste li { border-radius: 6px; background: var(--neutral-bg); overflow: hidden; }
  .akte-zeile { display: flex; align-items: center; gap: 8px; width: 100%; padding: 9px 12px; border: 0; background: none; color: var(--text); font: 13.5px var(--sans); cursor: pointer; text-align: left; } .akte-zeile:hover { background: var(--hover); }
  .akte-empf { padding: 0 12px 10px; font-size: 13px; color: var(--text-2); }
  .bulk { display: flex; flex-direction: column; gap: 8px; border-top: 1px solid var(--linie); padding-top: 14px; } .bulk-knoepfe { display: flex; flex-wrap: wrap; gap: 8px; }

  /* Infos unten */
  .raster { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 32px 40px; align-items: start; }
  .raster .karte { max-width: none; } .raster .karte h3 { font-size: 18px; }

  /* Ask ProcurePulse */
  .copilot { position: fixed; top: 0; right: 0; bottom: 0; width: min(420px, 100vw); z-index: 40; background: var(--flaeche); box-shadow: var(--popover); display: flex; flex-direction: column; gap: 12px; padding: 16px; animation: einblenden .16s ease-out; }
  .copilot header { display: flex; align-items: center; justify-content: space-between; } .cp-titel { display: inline-flex; align-items: center; gap: 8px; font-weight: 600; font-size: 15px; } .cp-titel .i { width: 16px; height: 16px; color: var(--akzent); }
  .cp-chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .cp-verlauf { flex: 1; min-height: 0; overflow: auto; display: flex; flex-direction: column; gap: 10px; }
  .cp-nachricht { white-space: pre-wrap; font-size: 14px; line-height: 1.55; padding: 8px 12px; border-radius: 8px; max-width: 94%; }
  .cp-nachricht.ich { align-self: flex-end; background: var(--akzent-hell); } .cp-nachricht.sys { align-self: flex-start; background: var(--neutral-bg); }
  .cp-form { display: flex; gap: 6px; } .cp-form input { flex: 1; } .cp-hinweis { margin: 0; }

  .toast { position: fixed; right: 24px; bottom: 24px; z-index: 50; display: flex; align-items: center; gap: 10px; max-width: 460px; background: var(--text); color: var(--bg); border-radius: 8px; padding: 10px 14px; font: 13.5px var(--sans); box-shadow: var(--popover); animation: einblenden .2s ease-out; transition: opacity .3s, transform .3s; }
  .toast .i { color: #7fd1a3; } .toast.aus { opacity: 0; transform: translateY(6px); pointer-events: none; }

  @media (max-width: 1000px) { .arbeitsraum { grid-template-columns: 1fr; gap: 24px; } .queue { position: static; max-height: 320px; } }
  @media (max-width: 760px) {
    .kopf { position: static; } .kopf-innen, .kopf-unten, main { padding-left: 16px; padding-right: 16px; } .marke span { display: none; }
    .aktionen { margin-left: 0; width: 100%; } .bearbeiter { width: 100%; margin: 0; } .bearbeiter input { flex: 1; width: auto; }
    .kopf-unten { padding-top: 24px; } .seitentitel { font-size: 26px; } .chips { margin-left: 0; }
    .kpis { grid-template-columns: 1fr 1fr; } .kpi, .kpi + .kpi { padding: 14px 12px 14px 0; border-left: 0; } .kpi:nth-child(even) { padding-left: 16px; border-left: 1px solid var(--linie); } .kpi:nth-child(n+3) { border-top: 1px solid var(--linie); }
    .ueb-raster { grid-template-columns: 1fr; } .gitter dt { flex-basis: 110px; } .copilot { width: 100vw; } .sortierung { margin-left: 0; width: 100%; padding: 6px 0; }
  }
  @media (prefers-reduced-motion: reduce) { .karte, .toast, .puls::after, .detail .karte, .detail .akte, .copilot { animation: none !important; transition: none !important; } }
  /* ---- Ganze Seite nutzen, Tastatur-Flow, Fokus, Mobile, warmes Dunkel ---- */
  body { display: flex; flex-direction: column; min-height: 100vh; }
  main { flex: 1; width: 100%; max-width: none; padding: 24px clamp(16px, 3vw, 56px) 72px; }
  .kopf-innen { max-width: none; padding: 0 clamp(16px, 3vw, 56px); }
  .kopf-unten { max-width: none; width: 100%; margin: 0; padding: 36px clamp(16px, 3vw, 56px) 0; }
  .kopf-innen { margin: 0; width: 100%; }
  .arbeitsraum { grid-template-columns: clamp(300px, 24vw, 420px) minmax(0, 1fr); gap: clamp(24px, 3vw, 56px); }
  .detail .karte, .akte { max-width: none; }
  .raster { grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); }
  @media (min-width: 1300px) {
    .detail .karte { display: grid; grid-template-columns: minmax(0, 1fr) clamp(280px, 22vw, 360px); column-gap: clamp(32px, 3vw, 56px); row-gap: 20px; align-content: start; }
    .detail .karte > header, .detail .karte > .empfehlung { grid-column: 1 / -1; }
    .detail .karte > .reiterleiste, .detail .karte > .tafel { grid-column: 1; }
    .detail .karte > .aktionsleiste { grid-column: 2; grid-row: 3 / span 4; align-self: start; position: sticky; top: 68px; border-top: 0; padding: 0; }
    .detail .karte > .aktionsleiste::before { content: "Aktionen"; font-size: 12.5px; font-weight: 600; color: var(--text-3); }
    .aktionsleiste .entscheidung { flex-direction: column; align-items: stretch; } .aktionsleiste .entscheidung form, .aktionsleiste .entscheidung .knopf { width: 100%; justify-content: center; }
    .aktionsleiste .weiter { flex-direction: column; align-items: stretch; } .aktionsleiste .weiter form, .aktionsleiste .weiter .knopf { width: 100%; justify-content: flex-start; }
  }
  .zurueck { display: none; align-items: center; gap: 6px; margin: 0 0 14px; padding: 5px 10px 5px 6px; border: 0; border-radius: 6px; background: none; color: var(--text-2); font: 500 14px var(--sans); cursor: pointer; }
  .zurueck:hover { background: var(--hover); color: var(--text); }
  .fokusband { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; padding: 8px 12px; border-radius: 6px; background: var(--akzent-hell); color: var(--akzent-dunkel); font-size: 13.5px; font-weight: 500; }
